#!/usr/bin/env python3
import json

def get_domain(attr, available, pending):
    """Return the current domain for attribute attr given available values and any pending constraint."""
    if attr in pending:
        if pending[attr] in available[attr]:
            return [pending[attr]]
        else:
            return []
    else:
        return available[attr]

def remove_value(available, attr, value):
    """Return a new available dictionary with value removed from the domain for attr."""
    new_avail = {a: list(vals) for a, vals in available.items()}
    if value in new_avail[attr]:
        new_avail[attr].remove(value)
    return new_avail

def global_constraints(houses):
    # Constraint: The person who owns a BMW 3 Series must be somewhere to the left of the tea drinker.
    idx_bmw = None
    idx_tea = None
    for i, h in enumerate(houses):
        if h["car"] == "bmw 3 series":
            idx_bmw = i
        if h["favorite drink"] == "tea":
            idx_tea = i
    if idx_bmw is not None and idx_tea is not None:
        if idx_bmw >= idx_tea:
            return False

    # Constraint: There is one house between Alice and the person who owns a Ford F-150.
    idx_alice = None
    idx_ford = None
    for i, h in enumerate(houses):
        if h["Name"] == "Alice":
            idx_alice = i
        if h["car"] == "ford f150":
            idx_ford = i
    if idx_alice is not None and idx_ford is not None:
        if abs(idx_alice - idx_ford) != 2:
            return False

    # Constraint: The doctor is directly left of the person who uses a OnePlus 9.
    for i, h in enumerate(houses):
        if h["occupation"] == "doctor" and i < 4:
            if houses[i+1]["phone"] != "oneplus 9":
                return False

    return True

def backtrack(index, houses, available, pending):
    if index == 5:
        if global_constraints(houses):
            return houses
        else:
            return None

    # We work in order: attributes order: "Name", "lunch", "car", "phone", "occupation", "favorite drink"
    for name in get_domain("Name", available, pending):
        # Clue 17: Eric is in the fourth house (house index 3)
        if index == 3 and name != "Eric":
            continue
        candidate = {}
        candidate["Name"] = name
        avail1 = remove_value(available, "Name", name)

        # For lunch:
        lunch_domain = get_domain("lunch", avail1, pending)
        # Clue 4: Alice loves stir fry.
        if name == "Alice":
            lunch_domain = [x for x in lunch_domain if x == "stir fry"]
        # Clue 19: The person who loves grilled cheese is Peter.
        if name == "Peter":
            lunch_domain = [x for x in lunch_domain if x == "grilled cheese"]
        for lunch in lunch_domain:
            candidate["lunch"] = lunch
            avail2 = remove_value(avail1, "lunch", lunch)

            # For car:
            car_domain = get_domain("car", avail2, pending)
            # Clue 16: Arnold owns a Toyota Camry.
            if name == "Arnold":
                car_domain = [x for x in car_domain if x == "toyota camry"]
            for car in car_domain:
                candidate["car"] = car
                avail3 = remove_value(avail2, "car", car)

                # For phone:
                phone_domain = get_domain("phone", avail3, pending)
                # Clue 3: Alice uses a Samsung Galaxy S21.
                if name == "Alice":
                    phone_domain = [x for x in phone_domain if x == "samsung galaxy s21"]
                for phone in phone_domain:
                    candidate["phone"] = phone
                    avail4 = remove_value(avail3, "phone", phone)

                    # For occupation:
                    occ_domain = get_domain("occupation", avail4, pending)
                    # Clue 7: Arnold is a doctor.
                    if name == "Arnold":
                        occ_domain = [x for x in occ_domain if x == "doctor"]
                    # Clue 14: Alice is an artist.
                    if name == "Alice":
                        occ_domain = [x for x in occ_domain if x == "artist"]
                    for occ in occ_domain:
                        candidate["occupation"] = occ
                        avail5 = remove_value(avail4, "occupation", occ)

                        # For favorite drink:
                        drink_domain = get_domain("favorite drink", avail5, pending)
                        for drink in drink_domain:
                            candidate["favorite drink"] = drink
                            avail6 = remove_value(avail5, "favorite drink", drink)

                            # Intra-house constraints:
                            # Clue 10 & 8: The person who loves stew uses an iPhone 13 and the iPhone user is the coffee drinker.
                            if candidate["lunch"] == "stew" and candidate["phone"] != "iphone 13":
                                continue
                            if candidate["phone"] == "iphone 13" and candidate["lunch"] != "stew":
                                continue
                            if candidate["phone"] == "iphone 13" and candidate["favorite drink"] != "coffee":
                                continue
                            if candidate["favorite drink"] == "coffee" and candidate["phone"] != "iphone 13":
                                continue
                            # Clue 1: The root beer lover is the person who owns a Honda Civic.
                            if candidate["car"] == "honda civic" and candidate["favorite drink"] != "root beer":
                                continue
                            # Clue 13: The person who uses a Google Pixel 6 is the tea drinker.
                            if candidate["phone"] == "google pixel 6" and candidate["favorite drink"] != "tea":
                                continue
                            # Clue 18: The person who uses a OnePlus 9 is the lawyer.
                            if candidate["phone"] == "oneplus 9" and candidate["occupation"] != "lawyer":
                                continue
                            # Clue 9: The engineer is the person who owns a BMW 3 Series.
                            if candidate["occupation"] == "engineer" and candidate["car"] != "bmw 3 series":
                                continue
                            if candidate["car"] == "bmw 3 series" and candidate["occupation"] != "engineer":
                                continue
                            # Clue 5: The tea drinker is not in the fifth house.
                            if index == 4 and candidate["favorite drink"] == "tea":
                                continue
                            # Clue 19: grilled cheese must belong to Peter.
                            if candidate["lunch"] == "grilled cheese" and candidate["Name"] != "Peter":
                                continue

                            # Neighbor (adjacent) constraints from the previous house:
                            if index > 0:
                                prev = houses[index - 1]
                                # Clue 2: The person who likes milk is directly left of the person who loves grilled cheese.
                                if prev["favorite drink"] == "milk" and candidate["lunch"] != "grilled cheese":
                                    continue
                                # Clue 12: The person who owns a Honda Civic is directly left of the person who loves spaghetti (spaghetti eater).
                                if prev["car"] == "honda civic" and candidate["lunch"] != "spaghetti":
                                    continue
                                # Clue 11: The doctor is directly left of the person who uses a OnePlus 9.
                                if prev["occupation"] == "doctor" and candidate["phone"] != "oneplus 9":
                                    continue

                            # Global check in partial assignment:
                            # Clue 6: The BMW 3 Series must be to the left of the tea drinker.
                            if candidate["favorite drink"] == "tea":
                                if not any(h["car"] == "bmw 3 series" for h in houses):
                                    continue

                            # Clue 15: There is one house between Alice and the person who owns a Ford F-150.
                            valid_gap = True
                            for j, h_obj in enumerate(houses):
                                if h_obj["Name"] == "Alice" and candidate["car"] == "ford f150":
                                    if abs(index - j) != 2:
                                        valid_gap = False
                                        break
                                if h_obj.get("car") == "ford f150" and candidate["Name"] == "Alice":
                                    if abs(index - j) != 2:
                                        valid_gap = False
                                        break
                            if not valid_gap:
                                continue
                            # Additionally, if both an Alice and a Ford F-150 have been assigned earlier, they must differ by exactly 2 houses.
                            alice_index = None
                            ford_index = None
                            for j, h_obj in enumerate(houses):
                                if h_obj["Name"] == "Alice":
                                    alice_index = j
                                if h_obj.get("car") == "ford f150":
                                    ford_index = j
                            if alice_index is not None and ford_index is not None:
                                if abs(alice_index - ford_index) != 2:
                                    continue

                            # Set up pending constraints for the next house.
                            pending_next = {}
                            # From Clue 2: If someone likes milk, the next house must have grilled cheese for lunch.
                            if candidate["favorite drink"] == "milk":
                                pending_next["lunch"] = "grilled cheese"
                            # From Clue 12: If someone owns a Honda Civic, the next house must have spaghetti for lunch.
                            if candidate["car"] == "honda civic":
                                if "lunch" in pending_next and pending_next["lunch"] != "spaghetti":
                                    continue
                                pending_next["lunch"] = "spaghetti"
                            # From Clue 11: If someone is a doctor, the next house must use a OnePlus 9.
                            if candidate["occupation"] == "doctor":
                                pending_next["phone"] = "oneplus 9"

                            new_houses = houses + [candidate.copy()]
                            result = backtrack(index + 1, new_houses, avail6, pending_next)
                            if result is not None:
                                return result
    return None

def solve():
    available = {
        "Name": ["Eric", "Peter", "Arnold", "Alice", "Bob"],
        "lunch": ["stir fry", "spaghetti", "stew", "grilled cheese", "pizza"],
        "car": ["ford f150", "tesla model 3", "bmw 3 series", "toyota camry", "honda civic"],
        "phone": ["iphone 13", "google pixel 6", "samsung galaxy s21", "oneplus 9", "huawei p50"],
        "occupation": ["teacher", "lawyer", "doctor", "artist", "engineer"],
        "favorite drink": ["tea", "milk", "water", "root beer", "coffee"]
    }
    pending = {}
    solution = backtrack(0, [], available, pending)
    if solution is None:
        sol = {"solution": {"header": ["House", "Name", "lunch", "car", "phone", "occupation", "favorite drink"], "rows": []}}
    else:
        rows = []
        for i, house in enumerate(solution):
            row = [str(i+1), house["Name"], house["lunch"], house["car"], house["phone"], house["occupation"], house["favorite drink"]]
            rows.append(row)
        sol = {"solution": {"header": ["House", "Name", "lunch", "car", "phone", "occupation", "favorite drink"], "rows": rows}}
    print(json.dumps(sol))

if __name__ == "__main__":
    solve()
